//! The document model and its encodings: [`Value`], [`Document`], `RDoc` v1 (data-model.md §4)
//! and canonical / extended JSON (data-model.md §2 notes).
//!
//! Documents travel as `RDoc` bytes; ids, parameters and option values as the value encoding (type
//! tag + payload, no header). These modules are a copy of the server's `rustegon-doc` codec
//! (PD-180): a client crate depends on no server crate, and `drivers/conformance/codec/*.yaml`
//! (generated by the server) pin both to the same bytes (TC-DRV-RS-001).

pub mod decimal;
pub mod error;
mod hex;
pub mod json;
pub mod limits;
pub mod oid;
pub mod rdoc;
pub mod value;

mod convert;

pub use self::{
    decimal::Decimal128,
    error::{DocError, DocResult},
    json::JsonMode,
    oid::ObjectId,
    value::{Document, Timestamp, Value},
};

/// Lowercase hex of `bytes` (vector files and diagnostics).
#[must_use]
pub fn to_hex(bytes: &[u8]) -> String {
    hex::encode(bytes)
}

/// Bytes of an even-length hex string (either case), `None` when it is not hex.
#[must_use]
pub fn from_hex(text: &str) -> Option<Vec<u8>> {
    let mut out = vec![0u8; text.len() / 2];
    if !text.len().is_multiple_of(2) {
        return None;
    }
    hex::decode_into(text, &mut out)?;
    Some(out)
}
